import Queue from 'yocto-queue';

export default function pLimit(concurrency) {
	let rejectOnClear = false;

	if (typeof concurrency === 'object') {
		({concurrency, rejectOnClear = false} = concurrency);
	}

	validateConcurrency(concurrency);

	if (typeof rejectOnClear !== 'boolean') {
		throw new TypeError('Expected `rejectOnClear` to be a boolean');
	}

	const queue = new Queue();
	let activeCount = 0;
	let idleWaiters = [];
	let idleCheckScheduled = false;

	const isIdle = () => activeCount === 0 && queue.size === 0;

	const scheduleIdleCheck = () => {
		// Resolve idle waiters only after a full macrotask boundary. All promise
		// reactions queued by a just-settled job (including a `.then` that enqueues
		// more work) run before a macrotask, so re-checking here avoids reporting
		// idle while a new job is about to be enqueued.
		if (idleCheckScheduled || idleWaiters.length === 0 || !isIdle()) {
			return;
		}

		idleCheckScheduled = true;
		setImmediate(() => {
			idleCheckScheduled = false;

			if (idleWaiters.length === 0 || !isIdle()) {
				return;
			}

			const waiters = idleWaiters;
			idleWaiters = [];

			for (const resolve of waiters) {
				resolve();
			}
		});
	};

	const resumeNext = () => {
		// Process the next queued function if we're under the concurrency limit
		if (activeCount < concurrency && queue.size > 0) {
			activeCount++;
			queue.dequeue().run();
		}
	};

	const next = () => {
		activeCount--;
		resumeNext();
		scheduleIdleCheck();
	};

	const run = async (function_, resolve, arguments_) => {
		// Execute the function and capture the result promise
		const result = (async () => function_(...arguments_))();

		// Resolve immediately with the promise (don't wait for completion)
		resolve(result);

		// Wait for the function to complete (success or failure)
		// We catch errors here to prevent unhandled rejections,
		// but the original promise rejection is preserved for the caller
		try {
			await result;
		} catch {}

		// Decrement active count and process next queued function
		next();
	};

	const enqueue = (function_, resolve, reject, arguments_) => {
		const queueItem = {reject};

		// Queue the internal resolve function instead of the run function
		// to preserve the asynchronous execution context.
		new Promise(internalResolve => { // eslint-disable-line promise/param-names
			queueItem.run = internalResolve;
			queue.enqueue(queueItem);
		}).then(run.bind(undefined, function_, resolve, arguments_)); // eslint-disable-line promise/prefer-await-to-then

		// Start processing immediately if we haven't reached the concurrency limit
		if (activeCount < concurrency) {
			resumeNext();
		}
	};

	const generator = (function_, ...arguments_) => new Promise((resolve, reject) => {
		enqueue(function_, resolve, reject, arguments_);
	});

	Object.defineProperties(generator, {
		activeCount: {
			get: () => activeCount,
		},
		pendingCount: {
			get: () => queue.size,
		},
		clearQueue: {
			value() {
				if (!rejectOnClear) {
					queue.clear();
					scheduleIdleCheck();
					return;
				}

				const abortError = AbortSignal.abort().reason;

				while (queue.size > 0) {
					queue.dequeue().reject(abortError);
				}

				scheduleIdleCheck();
			},
		},
		onIdle: {
			value() {
				if (isIdle()) {
					return Promise.resolve();
				}

				return new Promise(resolve => {
					idleWaiters.push(resolve);
					scheduleIdleCheck();
				});
			},
		},
		concurrency: {
			get: () => concurrency,

			set(newConcurrency) {
				validateConcurrency(newConcurrency);
				concurrency = newConcurrency;

				queueMicrotask(() => {
					// eslint-disable-next-line no-unmodified-loop-condition
					while (activeCount < concurrency && queue.size > 0) {
						resumeNext();
					}
				});
			},
		},
		map: {
			async value(iterable, function_) {
				const promises = [];

				try {
					Array.from(iterable, (value, index) => {
						const promise = generator(function_, value, index);
						promises.push(promise);
						return promise;
					});
				} catch (error) {
					// The iterable threw, so `Promise.all` never observes the already scheduled promises. Observe them here to avoid unhandled rejections.
					for (const promise of promises) {
						promise.catch(() => {}); // eslint-disable-line promise/prefer-await-to-then
					}

					throw error;
				}

				return Promise.all(promises);
			},
		},
	});

	return generator;
}

export function limitFunction(function_, options) {
	const limit = pLimit(options);

	const limitedFunction = (...arguments_) => limit(() => function_(...arguments_));
	Object.defineProperty(limitedFunction, 'clearQueue', {
		value: limit.clearQueue,
	});
	Object.defineProperty(limitedFunction, 'onIdle', {
		value: limit.onIdle,
	});

	return limitedFunction;
}

function validateConcurrency(concurrency) {
	if (!((Number.isInteger(concurrency) || concurrency === Number.POSITIVE_INFINITY) && concurrency > 0)) {
		throw new TypeError('Expected `concurrency` to be a number from 1 and up');
	}
}

export type LimitFunction = {
	/**
	The number of promises that are currently running.
	*/
	readonly activeCount: number;

	/**
	The number of promises that are waiting to run (i.e. their internal `fn` was not called yet).
	*/
	readonly pendingCount: number;

	/**
	Get or set the concurrency limit.
	*/
	concurrency: number;

	/**
	Discard pending promises that are waiting to run.

	This might be useful if you want to tear down the queue at the end of your program's lifecycle or discard any function calls referencing an intermediary state of your app.

	Note: This does not cancel promises that are already running.

	When `rejectOnClear` is enabled, pending promises are rejected with an `AbortError`.
	This is recommended if you await the returned promises, for example with `Promise.all`, so pending tasks do not remain unresolved after `clearQueue()`.
	*/
	clearQueue: () => void;

	/**
	Returns a promise that resolves when the limiter is idle.

	The limiter is idle when there are no running (or reserved) promises and nothing is waiting in the queue.
	Calling this on an already idle limiter resolves normally.

	Waiting for the queue to settle is useful for tests and for shutting down cleanly, for example before flushing logs or closing resources.
	*/
	onIdle: () => Promise<void>;

	/**
	Process an iterable of inputs with limited concurrency.

	The mapper function receives the item value and its index.

	If the iterable throws during iteration, the returned promise rejects with that error. Mapper functions that were already scheduled still run, and their results are discarded.

	This is a convenience function for processing inputs that arrive in batches. For more complex use cases, see [p-map](https://github.com/sindresorhus/p-map).

	@param iterable - An iterable containing an argument for the given function.
	@param mapperFunction - Promise-returning/async function.
	@returns A promise equivalent to `Promise.all(Array.from(iterable, (item, index) => limit(mapperFunction, item, index)))`.
	*/
	map: <Input, ReturnType> (
		iterable: Iterable<Input>,
		mapperFunction: (input: Input, index: number) => PromiseLike<ReturnType> | ReturnType
	) => Promise<ReturnType[]>;

	/**
	@param fn - Promise-returning/async function.
	@param arguments - Any arguments to pass through to `fn`. Support for passing arguments on to the `fn` is provided in order to be able to avoid creating unnecessary closures. You probably don't need this optimization unless you're pushing a *lot* of functions.

	Warning: Avoid calling the same `limit` function inside a function that is already limited by it. This can create a deadlock where inner tasks never run. Use a separate limiter for inner tasks.

	@returns The promise returned by calling `fn(...arguments)`.
	*/
	<Arguments extends unknown[], ReturnType>(
		function_: (...arguments_: Arguments) => PromiseLike<ReturnType> | ReturnType,
		...arguments_: Arguments
	): Promise<ReturnType>;
};

/**
Run multiple promise-returning & async functions with limited concurrency.

@param concurrency - Concurrency limit. Minimum: `1`. You can pass a number or an options object with a `concurrency` property.
@returns A `limit` function.

@example
```
import pLimit from 'p-limit';

const limit = pLimit(1);

const input = [
	limit(() => fetchSomething('foo')),
	limit(() => fetchSomething('bar')),
	limit(() => doSomething())
];

// Only one promise is run at once
const result = await Promise.all(input);
console.log(result);
```

@example
```
import pLimit from 'p-limit';

const limit = pLimit({concurrency: 1});
```
*/
export default function pLimit(concurrency: number | Options): LimitFunction;

export type Options = {
	/**
	Concurrency limit.

	Minimum: `1`.
	*/
	readonly concurrency: number;

	/**
	Reject pending promises with an `AbortError` when `clearQueue()` is called.

	Default: `false`.

	This is recommended if you await the returned promises, for example with `Promise.all`, so pending tasks do not remain unresolved after `clearQueue()`.
	*/
	readonly rejectOnClear?: boolean;
};

/**
Returns a function with limited concurrency.

The returned function manages its own concurrent executions, allowing you to call it multiple times without exceeding the specified concurrency limit.

Ideal for scenarios where you need to control the number of simultaneous executions of a single function, rather than managing concurrency across multiple functions.

@param function_ - Promise-returning/async function.
@return Function with limited concurrency.

@example
```
import {limitFunction} from 'p-limit';

const limitedFunction = limitFunction(async () => {
	return doSomething();
}, {concurrency: 1});

const input = Array.from({length: 10}, limitedFunction);

// Only one promise is run at once.
await Promise.all(input);
```
*/
export function limitFunction<Arguments extends unknown[], ReturnType>(
	function_: (...arguments_: Arguments) => PromiseLike<ReturnType>,
	options: Options
): ((...arguments_: Arguments) => Promise<ReturnType>) & Pick<LimitFunction, 'clearQueue' | 'onIdle'>;

import {setTimeout as delay} from 'node:timers/promises';
import test from 'ava';
import pLimit, {limitFunction} from './index.js';

test('onIdle resolves normally when already idle', async t => {
	const limit = pLimit(1);

	t.is(limit.activeCount, 0);
	t.is(limit.pendingCount, 0);

	await t.notThrowsAsync(limit.onIdle());
});

test('onIdle resolves when running and queued work is done', async t => {
	const limit = pLimit(2);
	let completed = 0;

	const jobs = Array.from({length: 5}, () => limit(async () => {
		await delay(20);
		completed++;
	}));

	await limit.onIdle();

	t.is(completed, 5);
	t.is(limit.activeCount, 0);
	t.is(limit.pendingCount, 0);
	await Promise.all(jobs);
});

test('onIdle resolves for multiple waiters, including when jobs reject', async t => {
	const limit = pLimit(1);
	const error = new Error('🦄');

	const rejected = limit(async () => {
		await delay(10);
		throw error;
	});

	const waiterOne = limit.onIdle();
	const waiterTwo = limit.onIdle();
	const waiterThree = limit.onIdle();

	await t.throwsAsync(rejected, {is: error});
	await t.notThrowsAsync(Promise.all([waiterOne, waiterTwo, waiterThree]));

	t.is(limit.activeCount, 0);
	t.is(limit.pendingCount, 0);
});

test('onIdle does not resolve early when a settled job enqueues another job', async t => {
	const limit = pLimit(1);
	const order = [];

	limit(async () => {
		order.push('first');
	}).then(() => { // eslint-disable-line promise/prefer-await-to-then
		order.push('then');
		limit(async () => {
			await delay(10);
			order.push('second');
		});
	});

	await limit.onIdle();

	t.deepEqual(order, ['first', 'then', 'second']);
	t.is(limit.activeCount, 0);
	t.is(limit.pendingCount, 0);
});

test('onIdle does not resolve early when a running job enqueues another job', async t => {
	const limit = pLimit(1);
	const order = [];

	await limit(async () => {
		order.push('first');
		await Promise.resolve();
		limit(async () => {
			order.push('second');
		});
	});

	await limit.onIdle();

	t.deepEqual(order, ['first', 'second']);
	t.is(limit.activeCount, 0);
	t.is(limit.pendingCount, 0);
});

test('onIdle counts reserved slots as active', async t => {
	const limit = pLimit(1);
	const running = limit(async () => {
		await delay(30);
	});

	let resolved = false;
	const idle = limit.onIdle().then(() => { // eslint-disable-line promise/prefer-await-to-then
		resolved = true;
	});

	await delay(5);

	t.is(limit.activeCount, 1);
	t.is(resolved, false);

	await idle;
	await running;
	t.is(limit.activeCount, 0);
});

test('onIdle re-resolves for a later idle period after new work is added', async t => {
	const limit = pLimit(1);

	await limit(async () => {
		await delay(10);
	});
	await limit.onIdle();

	await limit(async () => {
		await delay(10);
	});
	await t.notThrowsAsync(limit.onIdle());

	t.is(limit.activeCount, 0);
	t.is(limit.pendingCount, 0);
});

test('clearQueue releases onIdle waiters without rejectOnClear', async t => {
	const limit = pLimit({concurrency: 1, rejectOnClear: false});

	const running = limit(async () => {
		await delay(20);
	});

	const discarded = limit(async () => {});
	let discardedSettled = false;
	discarded.then(() => { // eslint-disable-line promise/prefer-await-to-then
		discardedSettled = true;
	});

	const idle = limit.onIdle();

	await Promise.resolve();
	t.is(limit.pendingCount, 1);

	limit.clearQueue();
	t.is(limit.pendingCount, 0);

	await t.notThrowsAsync(idle);

	t.is(limit.activeCount, 0);
	t.is(limit.pendingCount, 0);

	// The discarded promise intentionally stays unresolved when `rejectOnClear` is false.
	await running;
	await delay(10);
	t.is(discardedSettled, false);
});

test('clearQueue releases onIdle waiters while a job is still running', async t => {
	const limit = pLimit({concurrency: 1, rejectOnClear: false});

	const running = limit(async () => {
		await delay(20);
	});

	limit(async () => {});
	limit(async () => {});

	const idle = limit.onIdle();

	await Promise.resolve();
	limit.clearQueue();

	await t.notThrowsAsync(idle);
	await running;

	t.is(limit.activeCount, 0);
	t.is(limit.pendingCount, 0);
});

test('onIdle preserves FIFO order and concurrency behavior', async t => {
	const limit = pLimit(2);
	const order = [];
	let running = 0;
	let maxRunning = 0;

	const jobs = [1, 2, 3, 4, 5].map(value => limit(async () => {
		running++;
		maxRunning = Math.max(maxRunning, running);
		await delay(10);
		order.push(value);
		running--;
	}));

	await limit.onIdle();
	await Promise.all(jobs);

	t.deepEqual(order, [1, 2, 3, 4, 5]);
	t.is(maxRunning, 2);
});

test('onIdle still resolves after concurrency is increased mid-flight', async t => {
	const limit = pLimit(1);
	let running = 0;
	let maxRunning = 0;

	const jobs = Array.from({length: 4}, () => limit(async () => {
		running++;
		maxRunning = Math.max(maxRunning, running);
		await delay(10);
		running--;
	}));

	await delay(0);
	limit.concurrency = 3;

	await limit.onIdle();
	await Promise.all(jobs);

	t.is(maxRunning, 3);
	t.is(limit.activeCount, 0);
	t.is(limit.pendingCount, 0);
});

test('limitFunction exposes onIdle', async t => {
	const limitedFunction = limitFunction(async value => {
		await delay(10);
		return value;
	}, {concurrency: 1});

	const results = [limitedFunction(1), limitedFunction(2), limitedFunction(3)];

	t.is(typeof limitedFunction.onIdle, 'function');
	await limitedFunction.onIdle();

	t.deepEqual(await Promise.all(results), [1, 2, 3]);
});

test('limitFunction onIdle resolves normally when already idle', async t => {
	const limitedFunction = limitFunction(async () => {}, {concurrency: 1});

	await t.notThrowsAsync(limitedFunction.onIdle());
});

### limit.activeCount

The number of promises that are currently running.

### limit.pendingCount

The number of promises that are waiting to run (i.e. their internal `fn` was not called yet).

### limit.clearQueue()

Discard pending promises that are waiting to run.

This might be useful if you want to tear down the queue at the end of your program's lifecycle or discard any function calls referencing an intermediary state of your app.

Note: This does not cancel promises that are already running.

When `rejectOnClear` is enabled, pending promises are rejected with an `AbortError`.
This is recommended if you await the returned promises, for example with `Promise.all`, so pending tasks do not remain unresolved after `clearQueue()`.

### limit.concurrency

Get or set the concurrency limit.

### limit.onIdle()

Returns a promise that resolves when the limiter is idle.

The limiter is idle when there are no running (or reserved) promises and nothing is waiting in the queue. Calling this on an already idle limiter resolves normally.

This is useful for tests and for shutting down cleanly, for example before flushing logs or closing resources.

```js
import pLimit from 'p-limit';

const limit = pLimit(1);

limit(() => doSomething());
limit(() => doSomethingElse());

await limit.onIdle();
console.log('All work is done');
```

### limitFunction(fn, options) <sup>named export</sup>

Returns a function with limited concurrency.

The returned function manages its own concurrent executions, allowing you to call it multiple times without exceeding the specified concurrency limit.

Ideal for scenarios where you need to control the number of simultaneous executions of a single function, rather than managing concurrency across multiple functions.

```js
import {limitFunction} from 'p-limit';

const limitedFunction = limitFunction(async () => {
	return doSomething();
}, {concurrency: 1});

const input = Array.from({length: 10}, limitedFunction);

// Only one promise is run at once.
await Promise.all(input);
```

#### fn

Type: `Function`

Promise-returning/async function.

#### options

Type: `object`

#### concurrency

Type: `number`\
Minimum: `1`

Concurrency limit.

#### rejectOnClear

Type: `boolean`\
Default: `false`

Reject pending promises with an `AbortError` when `clearQueue()` is called.
This is recommended if you await the returned promises, for example with `Promise.all`, so pending tasks do not remain unresolved after `clearQueue()`.

### limitedFunction.clearQueue()

Discard pending calls that have not started yet.

When `rejectOnClear` is enabled, pending promises are rejected with an `AbortError`. Otherwise, their promises remain unresolved.

This does not cancel calls that are already running.

### limitedFunction.onIdle()

Returns a promise that resolves when the limiter is idle.

The limiter is idle when there are no running (or reserved) calls and nothing is waiting in the queue. Calling this on an already idle limiter resolves normally.

```js
import {limitFunction} from 'p-limit';

const limitedFunction = limitFunction(async () => {
	return doSomething();
}, {concurrency: 1});

limitedFunction();
limitedFunction();

await limitedFunction.onIdle();
console.log('All calls are done');
```

