import {setTimeout as delay} from 'node:timers/promises';
import test from 'ava';
import pLimit, {limitFunction} from './index.js';

test('onIdle still resolves normally without options', async t => {
	const limit = pLimit(1);

	await t.notThrowsAsync(limit.onIdle());

	limit(async () => {
		await delay(10);
	});

	await t.notThrowsAsync(limit.onIdle());
});

test('onIdle rejects a pre-aborted signal even when idle', async t => {
	const limit = pLimit(1);
	const controller = new AbortController();
	const reason = new Error('🦄');
	controller.abort(reason);

	await t.throwsAsync(limit.onIdle({signal: controller.signal}), {is: reason});
	t.is(limit.activeCount, 0);
	t.is(limit.pendingCount, 0);
});

test('onIdle with an unaborted signal resolves as before', async t => {
	const limit = pLimit(1);
	const controller = new AbortController();

	const running = limit(async () => {
		await delay(20);
	});

	await t.notThrowsAsync(limit.onIdle({signal: controller.signal}));
	await running;
});

test('aborting rejects only that waiter and leaves jobs and other waiters intact', async t => {
	const limit = pLimit(1);
	const controller = new AbortController();
	const reason = new Error('aborted');
	let completed = 0;

	const jobs = Array.from({length: 3}, () => limit(async () => {
		await delay(20);
		completed++;
	}));

	const abortedWaiter = limit.onIdle({signal: controller.signal});
	const survivingWaiter = limit.onIdle();

	controller.abort(reason);

	await t.throwsAsync(abortedWaiter, {is: reason});
	await t.notThrowsAsync(survivingWaiter);

	t.is(completed, 3);
	t.is(limit.activeCount, 0);
	t.is(limit.pendingCount, 0);
	await Promise.all(jobs);
});

test('aborting does not cancel queued jobs', async t => {
	const limit = pLimit(1);
	const controller = new AbortController();
	const order = [];

	limit(async () => {
		await delay(20);
		order.push('first');
	});
	limit(async () => {
		order.push('second');
	});
	limit(async () => {
		order.push('third');
	});

	const waiter = limit.onIdle({signal: controller.signal});
	controller.abort(new Error('nope'));

	await t.throwsAsync(waiter);

	await limit.onIdle();
	t.deepEqual(order, ['first', 'second', 'third']);
});

test('abort listener is removed after the waiter settles', async t => {
	const limit = pLimit(1);
	const controller = new AbortController();

	const running = limit(async () => {
		await delay(20);
	});

	const idle = limit.onIdle({signal: controller.signal});
	await idle;
	await running;

	// Aborting after settlement must be a no-op: a stale listener would try to
	// settle an already-settled promise and could also keep the signal alive.
	controller.abort(new Error('late'));

	await t.notThrowsAsync(limit.onIdle());
	t.is(limit.activeCount, 0);
	t.is(limit.pendingCount, 0);
});

test('limitFunction onIdle supports an abort signal', async t => {
	const limitedFunction = limitFunction(async value => {
		await delay(20);
		return value;
	}, {concurrency: 1});
	const controller = new AbortController();

	const results = [limitedFunction(1), limitedFunction(2)];
	const abortedWaiter = limitedFunction.onIdle({signal: controller.signal});
	const survivingWaiter = limitedFunction.onIdle();

	const reason = new Error('aborted');
	controller.abort(reason);

	await t.throwsAsync(abortedWaiter, {is: reason});
	await t.notThrowsAsync(survivingWaiter);
	t.deepEqual(await Promise.all(results), [1, 2]);
});

test('limitFunction onIdle rejects a pre-aborted signal', async t => {
	const limitedFunction = limitFunction(async () => {}, {concurrency: 1});
	const controller = new AbortController();
	const reason = new Error('pre-aborted');
	controller.abort(reason);

	await t.throwsAsync(limitedFunction.onIdle({signal: controller.signal}), {is: reason});
});

